/**
 * Minimal, dependency-free JSON model used by the {@code jsonf:}, {@code arrf:} and aggregate functions.
 * <p>
 * JSON documents are represented with plain Java objects: {@link Map} (insertion ordered) for objects, {@link List} for
 * arrays, {@link String}, {@link Boolean}, {@link #NULL} for JSON {@code null}, and for numbers {@link BigInteger}
 * (integral lexical form), {@link BigDecimal} (fractional lexical form) or {@link Double} (exponent lexical form).
 * Parsed trees must be treated as immutable; {@link #deepCopy(Object)} is available for functions that modify.
 * <p>
 * RDF terms are mapped to JSON losslessly: simple/xsd:string literals become JSON strings, numeric literals JSON
 * numbers, xsd:boolean literals JSON booleans, rdf:JSON literals are embedded, IRIs and blank nodes become
 * {@code {"@id": "..."}} and any other literal {@code {"@value": "...", "@type": "..."}} or
 * {@code {"@value": "...", "@language": "..."}} (JSON-LD style). The reverse mapping restores the original term.
 */
@Experimental
public final class JsonSupport {

	/** The JSON {@code null} value (distinct from a missing value). */
	public static final Object NULL = new Object() {
		@Override
		public String toString() {
			return "null";
		}
	};

	private static final int PARSE_CACHE_SIZE = 16;

	private static final ThreadLocal<LinkedHashMap<String, Object>> PARSE_CACHE = ThreadLocal
			.withInitial(() -> new LinkedHashMap<>(32, 0.75f, true) {
				private static final long serialVersionUID = 1L;

				@Override
				protected boolean removeEldestEntry(Map.Entry<String, Object> eldest) {
					return size() > PARSE_CACHE_SIZE;
				}
			});

	private JsonSupport() {
	}

	// ------------------------------------------------------------------ parsing

	/** Parses the JSON document held by a {@code rdf:JSON} or string literal argument (cached per thread). */
	public static Object parseArgument(Function function, Value arg) {
		if (!(arg instanceof Literal literal)) {
			throw FunctionArgs.typeError(function, arg, "a JSON literal");
		}
		CoreDatatype datatype = literal.getCoreDatatype();
		if (datatype != CoreDatatype.RDF.JSON && !QueryEvaluationUtility.isStringLiteral(literal)) {
			throw FunctionArgs.typeError(function, arg, "an rdf:JSON or string literal");
		}
		try {
			return parseCached(literal.getLabel());
		} catch (IllegalArgumentException e) {
			throw new ValueExprEvaluationException("Invalid JSON argument for " + function.getURI() + ": "
					+ e.getMessage(), e);
		}
	}

	public static Object parseCached(String json) {
		LinkedHashMap<String, Object> cache = PARSE_CACHE.get();
		Object parsed = cache.get(json);
		if (parsed == null) {
			parsed = parse(json);
			cache.put(json, parsed);
		}
		return parsed;
	}

	/** Parses a JSON text (RFC 8259); throws {@link IllegalArgumentException} on malformed input. */
	public static Object parse(String json) {
		Parser parser = new Parser(json);
		Object value = parser.readValue();
		parser.skipWhitespace();
		if (parser.pos != json.length()) {
			throw parser.error("Unexpected trailing content");
		}
		return value;
	}

	private static final class Parser {
		private final String s;
		private int pos;

		Parser(String s) {
			this.s = s;
		}

		IllegalArgumentException error(String message) {
			return new IllegalArgumentException(message + " at position " + pos);
		}

		void skipWhitespace() {
			while (pos < s.length()) {
				char c = s.charAt(pos);
				if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
					pos++;
				} else {
					break;
				}
			}
		}

		Object readValue() {
			skipWhitespace();
			if (pos >= s.length()) {
				throw error("Unexpected end of JSON");
			}
			char c = s.charAt(pos);
			switch (c) {
			case '{':
				return readObject();
			case '[':
				return readArray();
			case '"':
				return readString();
			case 't':
				expect("true");
				return Boolean.TRUE;
			case 'f':
				expect("false");
				return Boolean.FALSE;
			case 'n':
				expect("null");
				return NULL;
			default:
				if (c == '-' || (c >= '0' && c <= '9')) {
					return readNumber();
				}
				throw error("Unexpected character '" + c + "'");
			}
		}

		private void expect(String word) {
			if (!s.startsWith(word, pos)) {
				throw error("Expected '" + word + "'");
			}
			pos += word.length();
		}

		private Map<String, Object> readObject() {
			pos++; // {
			Map<String, Object> map = new LinkedHashMap<>();
			skipWhitespace();
			if (pos < s.length() && s.charAt(pos) == '}') {
				pos++;
				return map;
			}
			while (true) {
				skipWhitespace();
				if (pos >= s.length() || s.charAt(pos) != '"') {
					throw error("Expected object key");
				}
				String key = readString();
				skipWhitespace();
				if (pos >= s.length() || s.charAt(pos) != ':') {
					throw error("Expected ':'");
				}
				pos++;
				map.put(key, readValue());
				skipWhitespace();
				if (pos >= s.length()) {
					throw error("Unterminated object");
				}
				char c = s.charAt(pos++);
				if (c == '}') {
					return map;
				}
				if (c != ',') {
					throw error("Expected ',' or '}'");
				}
			}
		}

		private List<Object> readArray() {
			pos++; // [
			List<Object> list = new ArrayList<>();
			skipWhitespace();
			if (pos < s.length() && s.charAt(pos) == ']') {
				pos++;
				return list;
			}
			while (true) {
				list.add(readValue());
				skipWhitespace();
				if (pos >= s.length()) {
					throw error("Unterminated array");
				}
				char c = s.charAt(pos++);
				if (c == ']') {
					return list;
				}
				if (c != ',') {
					throw error("Expected ',' or ']'");
				}
			}
		}

		private String readString() {
			pos++; // opening quote
			int start = pos;
			// fast path: no escapes
			while (pos < s.length()) {
				char c = s.charAt(pos);
				if (c == '"') {
					String result = s.substring(start, pos);
					pos++;
					return result;
				}
				if (c == '\\') {
					break;
				}
				if (c < 0x20) {
					throw error("Unescaped control character in string");
				}
				pos++;
			}
			StringBuilder sb = new StringBuilder(s.length() - start);
			sb.append(s, start, pos);
			while (pos < s.length()) {
				char c = s.charAt(pos++);
				if (c == '"') {
					return sb.toString();
				}
				if (c == '\\') {
					if (pos >= s.length()) {
						break;
					}
					char e = s.charAt(pos++);
					switch (e) {
					case '"':
					case '\\':
					case '/':
						sb.append(e);
						break;
					case 'b':
						sb.append('\b');
						break;
					case 'f':
						sb.append('\f');
						break;
					case 'n':
						sb.append('\n');
						break;
					case 'r':
						sb.append('\r');
						break;
					case 't':
						sb.append('\t');
						break;
					case 'u':
						if (pos + 4 > s.length()) {
							throw error("Invalid unicode escape");
						}
						try {
							sb.append((char) Integer.parseInt(s.substring(pos, pos + 4), 16));
						} catch (NumberFormatException ex) {
							throw error("Invalid unicode escape");
						}
						pos += 4;
						break;
					default:
						throw error("Invalid escape '\\" + e + "'");
					}
				} else if (c < 0x20) {
					throw error("Unescaped control character in string");
				} else {
					sb.append(c);
				}
			}
			throw error("Unterminated string");
		}

		private Object readNumber() {
			int start = pos;
			boolean fraction = false;
			boolean exponent = false;
			if (s.charAt(pos) == '-') {
				pos++;
			}
			while (pos < s.length()) {
				char c = s.charAt(pos);
				if (c >= '0' && c <= '9') {
					pos++;
				} else if (c == '.' && !fraction && !exponent) {
					fraction = true;
					pos++;
				} else if ((c == 'e' || c == 'E') && !exponent) {
					exponent = true;
					pos++;
					if (pos < s.length() && (s.charAt(pos) == '+' || s.charAt(pos) == '-')) {
						pos++;
					}
				} else {
					break;
				}
			}
			String text = s.substring(start, pos);
			try {
				if (exponent) {
					return Double.parseDouble(text);
				}
				if (fraction) {
					return new BigDecimal(text);
				}
				return new BigInteger(text);
			} catch (NumberFormatException e) {
				throw error("Invalid number '" + text + "'");
			}
		}
	}

	// ------------------------------------------------------------------ writing

	public static String write(Object json) {
		StringBuilder sb = new StringBuilder(64);
		write(json, sb);
		return sb.toString();
	}

	@SuppressWarnings("unchecked")
	public static void write(Object json, StringBuilder sb) {
		if (json == null || json == NULL) {
			sb.append("null");
		} else if (json instanceof String string) {
			writeString(string, sb);
		} else if (json instanceof Boolean || json instanceof BigInteger) {
			sb.append(json);
		} else if (json instanceof BigDecimal decimal) {
			sb.append(decimal.toPlainString());
		} else if (json instanceof Double d) {
			if (d.isNaN() || d.isInfinite()) {
				writeString(d.toString(), sb);
			} else {
				sb.append(d.doubleValue());
			}
		} else if (json instanceof Number number) {
			sb.append(number);
		} else if (json instanceof Map) {
			sb.append('{');
			boolean first = true;
			for (Map.Entry<String, Object> entry : ((Map<String, Object>) json).entrySet()) {
				if (!first) {
					sb.append(',');
				}
				first = false;
				writeString(entry.getKey(), sb);
				sb.append(':');
				write(entry.getValue(), sb);
			}
			sb.append('}');
		} else if (json instanceof List) {
			sb.append('[');
			boolean first = true;
			for (Object element : (List<Object>) json) {
				if (!first) {
					sb.append(',');
				}
				first = false;
				write(element, sb);
			}
			sb.append(']');
		} else {
			throw new IllegalArgumentException("Not a JSON value: " + json.getClass());
		}
	}

	public static void writeString(String s, StringBuilder sb) {
		sb.append('"');
		int start = 0;
		int length = s.length();
		for (int i = 0; i < length; i++) {
			char c = s.charAt(i);
			String escape = null;
			switch (c) {
			case '"':
				escape = "\\\"";
				break;
			case '\\':
				escape = "\\\\";
				break;
			case '\n':
				escape = "\\n";
				break;
			case '\r':
				escape = "\\r";
				break;
			case '\t':
				escape = "\\t";
				break;
			case '\b':
				escape = "\\b";
				break;
			case '\f':
				escape = "\\f";
				break;
			default:
				if (c < 0x20) {
					escape = String.format("\\u%04x", (int) c);
				}
			}
			if (escape != null) {
				sb.append(s, start, i).append(escape);
				start = i + 1;
			}
		}
		sb.append(s, start, length).append('"');
	}

	/** Creates an {@code rdf:JSON} literal holding the serialisation of {@code json}. */
	public static Literal jsonLiteral(ValueFactory vf, Object json) {
		return vf.createLiteral(write(json), CoreDatatype.RDF.JSON);
	}

	// ------------------------------------------------------------------ RDF term mapping

	/** Maps an RDF term to its JSON representation (see class documentation). */
	public static Object toJson(Value value) {
		if (value instanceof Literal literal) {
			CoreDatatype datatype = literal.getCoreDatatype();
			if (datatype == CoreDatatype.XSD.STRING) {
				return literal.getLabel();
			}
			if (datatype == CoreDatatype.RDF.JSON) {
				return parseCached(literal.getLabel());
			}
			if (datatype == CoreDatatype.XSD.BOOLEAN) {
				return literal.booleanValue();
			}
			if (datatype.isXSDDatatype() && ((CoreDatatype.XSD) datatype).isNumericDatatype()) {
				try {
					switch (FunctionArgs.numericKind(literal)) {
					case INTEGER:
						return literal.integerValue();
					case DECIMAL:
						return literal.decimalValue();
					default:
						return literal.doubleValue();
					}
				} catch (NumberFormatException e) {
					// ill-formed numeric literal: fall through to the generic encoding
				}
			}
			Map<String, Object> object = new LinkedHashMap<>(2);
			object.put("@value", literal.getLabel());
			if (literal.getLanguage().isPresent()) {
				object.put("@language", literal.getLanguage().get());
				if (literal.getBaseDirection() != Literal.BaseDirection.NONE) {
					object.put("@direction", literal.getBaseDirection().name().toLowerCase());
				}
			} else {
				object.put("@type", literal.getDatatype().stringValue());
			}
			return object;
		}
		if (value instanceof IRI iri) {
			Map<String, Object> object = new LinkedHashMap<>(1);
			object.put("@id", iri.stringValue());
			return object;
		}
		if (value instanceof BNode bnode) {
			Map<String, Object> object = new LinkedHashMap<>(1);
			object.put("@id", "_:" + bnode.getID());
			return object;
		}
		throw new ValueExprEvaluationException("Cannot represent " + value + " as JSON");
	}

	/**
	 * Maps a JSON value back to an RDF term. Objects and arrays that are not JSON-LD style term objects become
	 * {@code rdf:JSON} literals; JSON {@code null} raises an evaluation error (SPARQL has no null).
	 */
	@SuppressWarnings("unchecked")
	public static Value toValue(Object json, ValueFactory vf) {
		if (json == null || json == NULL) {
			throw new ValueExprEvaluationException("JSON null has no RDF term representation");
		}
		if (json instanceof String string) {
			return vf.createLiteral(string);
		}
		if (json instanceof Boolean bool) {
			return vf.createLiteral(bool.booleanValue());
		}
		if (json instanceof BigInteger integer) {
			return vf.createLiteral(integer);
		}
		if (json instanceof BigDecimal decimal) {
			return vf.createLiteral(decimal);
		}
		if (json instanceof Double d) {
			return vf.createLiteral(d.doubleValue());
		}
		if (json instanceof Number number) {
			return vf.createLiteral(number.doubleValue());
		}
		if (json instanceof Map) {
			Map<String, Object> object = (Map<String, Object>) json;
			Object id = object.get("@id");
			if (id instanceof String idString && object.size() == 1) {
				if (idString.startsWith("_:")) {
					return vf.createBNode(idString.substring(2));
				}
				return vf.createIRI(idString);
			}
			Object literalValue = object.get("@value");
			if (literalValue instanceof String label && object.size() <= 3) {
				Object language = object.get("@language");
				Object type = object.get("@type");
				if (language instanceof String lang && type == null) {
					Object direction = object.get("@direction");
					if (direction instanceof String dir) {
						return vf.createLiteral(label, lang, Literal.BaseDirection.valueOf(dir.toUpperCase()));
					}
					if (object.size() == 2) {
						return vf.createLiteral(label, lang);
					}
				} else if (type instanceof String typeIri && language == null && object.size() == 2) {
					return vf.createLiteral(label, vf.createIRI(typeIri));
				}
			}
		}
		return jsonLiteral(vf, json);
	}

	/** A JSON array of the JSON mappings of the given RDF terms. */
	public static List<Object> toJsonArray(Iterable<? extends Value> values) {
		List<Object> list = new ArrayList<>();
		for (Value value : values) {
			list.add(toJson(value));
		}
		return list;
	}

	/** A JSON array of plain strings. */
	public static List<Object> stringArray(Iterable<String> strings) {
		List<Object> list = new ArrayList<>();
		for (String s : strings) {
			list.add(s);
		}
		return list;
	}

	@SuppressWarnings("unchecked")
	public static Object deepCopy(Object json) {
		if (json instanceof Map) {
			Map<String, Object> copy = new LinkedHashMap<>();
			for (Map.Entry<String, Object> entry : ((Map<String, Object>) json).entrySet()) {
				copy.put(entry.getKey(), deepCopy(entry.getValue()));
			}
			return copy;
		}
		if (json instanceof List) {
			List<Object> source = (List<Object>) json;
			List<Object> copy = new ArrayList<>(source.size());
			for (Object element : source) {
				copy.add(deepCopy(element));
			}
			return copy;
		}
		return json;
	}

	public static boolean isScalar(Object json) {
		return !(json instanceof Map) && !(json instanceof List);
	}

	/** JSON equality with numeric comparison by value (so that {@code 1}, {@code 1.0} and {@code 1e0} are equal). */
	@SuppressWarnings("unchecked")
	public static boolean jsonEquals(Object a, Object b) {
		if (a == b) {
			return true;
		}
		if (a == null || b == null || a == NULL || b == NULL) {
			return false;
		}
		if (a instanceof Number na && b instanceof Number nb) {
			return toBigDecimal(na).compareTo(toBigDecimal(nb)) == 0;
		}
		if (a instanceof Map && b instanceof Map) {
			Map<String, Object> ma = (Map<String, Object>) a;
			Map<String, Object> mb = (Map<String, Object>) b;
			if (ma.size() != mb.size()) {
				return false;
			}
			for (Map.Entry<String, Object> entry : ma.entrySet()) {
				if (!mb.containsKey(entry.getKey()) || !jsonEquals(entry.getValue(), mb.get(entry.getKey()))) {
					return false;
				}
			}
			return true;
		}
		if (a instanceof List && b instanceof List) {
			List<Object> la = (List<Object>) a;
			List<Object> lb = (List<Object>) b;
			if (la.size() != lb.size()) {
				return false;
			}
			for (int i = 0; i < la.size(); i++) {
				if (!jsonEquals(la.get(i), lb.get(i))) {
					return false;
				}
			}
			return true;
		}
		return a.equals(b);
	}

	private static BigDecimal toBigDecimal(Number n) {
		if (n instanceof BigDecimal d) {
			return d;
		}
		if (n instanceof BigInteger i) {
			return new BigDecimal(i);
		}
		double d = n.doubleValue();
		if (Double.isNaN(d) || Double.isInfinite(d)) {
			return BigDecimal.ZERO;
		}
		return BigDecimal.valueOf(d);
	}

	/** The xsd datatype IRI used for a JSON number mapped back to RDF; exposed for tests. */
	public static IRI numberDatatype(Object json) {
		if (json instanceof BigInteger) {
			return XSD.INTEGER;
		}
		if (json instanceof BigDecimal) {
			return XSD.DECIMAL;
		}
		return XSD.DOUBLE;
	}
}
